procedure:public.link_artist_production(.source_code:
DECLARE
  v_id uuid;
BEGIN
  IF p_role NOT IN ('producer', 'beatmaker', 'co-producer', 'executive_producer') THEN
    RETURN QUERY SELECT false, 'invalid_role'::text, NULL::uuid;
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.artists WHERE id = p_producer_id) THEN
    RETURN QUERY SELECT false, 'producer_not_found'::text, NULL::uuid;
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tracks WHERE id = p_track_id) THEN
    RETURN QUERY SELECT false, 'track_not_found'::text, NULL::uuid;
    RETURN;
  END IF;

  INSERT INTO public.artist_productions AS production (
    producer_id, track_id, role, credit_source, credit_note,
    confidence, is_verified, created_by
  )
  VALUES (
    p_producer_id, p_track_id, p_role, p_credit_source, p_credit_note,
    LEAST(GREATEST(COALESCE(p_confidence, 1.00), 0), 1), COALESCE(p_is_verified, false), p_created_by
  )
  ON CONFLICT (producer_id, track_id) DO UPDATE
  SET role = EXCLUDED.role,
      credit_note = COALESCE(EXCLUDED.credit_note, production.credit_note),
      -- Un crédit déjà vérifié n'est jamais rétrogradé par une collecte.
      credit_source = CASE
        WHEN production.is_verified THEN production.credit_source
        ELSE EXCLUDED.credit_source
      END,
      confidence = GREATEST(production.confidence, EXCLUDED.confidence),
      is_verified = production.is_verified OR EXCLUDED.is_verified,
      updated_at = now()
  RETURNING production.id INTO v_id;

  INSERT INTO public.track_artists (track_id, artist_id, role, billing_order)
  VALUES (p_track_id, p_producer_id, 'producer', NULL)
  ON CONFLICT (track_id, artist_id, role) DO NOTHING;

  RETURN QUERY SELECT true, 'ok'::text, v_id;
END;

procedure:public.link_artist_production(.definition:
CREATE OR REPLACE FUNCTION public.link_artist_production(p_producer_id uuid, p_track_id uuid, p_role text DEFAULT 'producer'::text, p_credit_source text DEFAULT 'manual_admin'::text, p_credit_note text DEFAULT NULL::text, p_confidence numeric DEFAULT 1.00, p_is_verified boolean DEFAULT false, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(success boolean, message text, production_id uuid)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF p_role NOT IN ('producer', 'beatmaker', 'co-producer', 'executive_producer') THEN
    RETURN QUERY SELECT false, 'invalid_role'::text, NULL::uuid;
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.artists WHERE id = p_producer_id) THEN
    RETURN QUERY SELECT false, 'producer_not_found'::text, NULL::uuid;
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tracks WHERE id = p_track_id) THEN
    RETURN QUERY SELECT false, 'track_not_found'::text, NULL::uuid;
    RETURN;
  END IF;

  INSERT INTO public.artist_productions AS production (
    producer_id, track_id, role, credit_source, credit_note,
    confidence, is_verified, created_by
  )
  VALUES (
    p_producer_id, p_track_id, p_role, p_credit_source, p_credit_note,
    LEAST(GREATEST(COALESCE(p_confidence, 1.00), 0), 1), COALESCE(p_is_verified, false), p_created_by
  )
  ON CONFLICT (producer_id, track_id) DO UPDATE
  SET role = EXCLUDED.role,
      credit_note = COALESCE(EXCLUDED.credit_note, production.credit_note),
      -- Un crédit déjà vérifié n'est jamais rétrogradé par une collecte.
      credit_source = CASE
        WHEN production.is_verified THEN production.credit_source
        ELSE EXCLUDED.credit_source
      END,
      confidence = GREATEST(production.confidence, EXCLUDED.confidence),
      is_verified = production.is_verified OR EXCLUDED.is_verified,
      updated_at = now()
  RETURNING production.id INTO v_id;

  INSERT INTO public.track_artists (track_id, artist_id, role, billing_order)
  VALUES (p_track_id, p_producer_id, 'producer', NULL)
  ON CONFLICT (track_id, artist_id, role) DO NOTHING;

  RETURN QUERY SELECT true, 'ok'::text, v_id;
END;
$function$

procedure:public.link_youtube_video_to_t.source_code:
DECLARE
  v_asset_id uuid;
BEGIN
  IF p_youtube_video_id IS NULL THEN
    RETURN QUERY SELECT false, NULL::uuid, 'missing_video_id'::text; RETURN;
  END IF;
  IF p_track_id IS NULL THEN
    RETURN QUERY SELECT false, NULL::uuid, 'missing_track_id'::text; RETURN;
  END IF;
  IF p_asset_role IS NULL OR p_asset_role NOT IN (
    'primary', 'lyric', 'visualizer', 'live', 'audio', 'remix', 'other'
  ) THEN
    RETURN QUERY SELECT false, NULL::uuid, 'invalid_asset_role'::text; RETURN;
  END IF;

  -- Lock the video row to prevent concurrent changes
  PERFORM 1 FROM public.youtube_videos
  WHERE id = p_youtube_video_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::uuid, 'video_not_found'::text; RETURN;
  END IF;

  -- Verify track exists
  PERFORM 1 FROM public.tracks WHERE id = p_track_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::uuid, 'track_not_found'::text; RETURN;
  END IF;

  -- Remove ALL existing associations for this video (ensures single canonical track)
  DELETE FROM public.youtube_track_assets
  WHERE youtube_video_id = p_youtube_video_id
    AND track_id <> p_track_id;

  -- Upsert the canonical association
  INSERT INTO public.youtube_track_assets (
    track_id, youtube_video_id, asset_role, is_primary, linked_by, linked_at
  ) VALUES (
    p_track_id, p_youtube_video_id, p_asset_role, p_is_primary, p_linked_by, clock_timestamp()
  )
  ON CONFLICT (track_id, youtube_video_id) DO UPDATE SET
    asset_role = EXCLUDED.asset_role,
    is_primary = EXCLUDED.is_primary,
    linked_by = EXCLUDED.linked_by,
    linked_at = EXCLUDED.linked_at
  RETURNING id INTO v_asset_id;

  -- Update canonical track_id on youtube_videos
  UPDATE public.youtube_videos SET track_id = p_track_id WHERE id = p_youtube_video_id;

  RETURN QUERY SELECT true, v_asset_id, 'ok'::text;
END;

